/// File extension/name mappings
pub syntax_mapping: SyntaxMapping<'a>,

/// Suffixes that should be ignored for syntax detection
pub ignored_suffixes: Vec<String>,

/// If we find an ignored suffix on the file name, e.g. '~', we strip it and
/// then try again without it.
pub fn try_with_stripped_suffix<T, F>(
    ignored_suffixes: &[String],
    file_name: &OsStr,
    func: F,
) -> Result<Option<T>>
where
    F: Fn(&OsStr) -> Result<Option<T>>,
{
    let mut from_stripped = None;
    // Use the ignored suffixes from the command line first and then the
    // built-in suffixes.
    let suffixes = ignored_suffixes
        .iter()
        .chain(&IGNORED_SUFFIXES)
        .map(|suffix| suffix.as_str());
    if let Some(file_str) = Path::new(file_name).to_str() {
        for suffix in suffixes {
            if let Some(stripped_filename) = file_str.strip_suffix(suffix) {
                from_stripped = func(OsStr::new(stripped_filename))?;
                break;
            }
        }
    }
    Ok(from_stripped)
}

